    public bool CanPlayCard(
        CombatPredictionSimulator simulator,
        PredictedCard card,
        out int energyCost,
        out int starCost)
    {
        energyCost = 0;
        starCost = 0;
        if (IsCardPlayPrevented(simulator, card))
